@triton.jit(do_not_specialize=["nidx", "nnode", "nz", "ny", "nx", "cy", "cx"])
def gather_idx_kernel(base_ptr, loc_ptr, out_ptr, idx_ptr, nidx, nnode, nz, ny, nx, cy, cx, BLOCK: tl.constexpr):
    """out[n,r] = base[n,r] + sum_{a=0..7} loc[cell(n,a), a, r] in fixed vertex order (no atomics)."""
    j = tl.program_id(0)*BLOCK+tl.arange(0, BLOCK)
    mj = j < nidx
    i = tl.load(idx_ptr+j, mask=mj, other=nnode*3).to(tl.int64)
    m = mj & (i < nnode*3)
    n = i//3
    r = i % 3
    x = n % nx
    y = (n//nx) % ny
    z = n//(nx*ny)
    acc = tl.load(base_ptr+i, mask=m, other=0.)
    x0 = x-0; y0 = y-0; z0 = z-0
    ok0 = m & (x0 >= 0) & (x0 < cx) & (y0 >= 0) & (y0 < cy) & (z0 >= 0) & (z0 < nz-1)
    cell0 = (z0*cy+y0)*cx+x0
    acc += tl.load(loc_ptr+cell0*24+0+r, mask=ok0, other=0.)
    x1 = x-1; y1 = y-0; z1 = z-0
    ok1 = m & (x1 >= 0) & (x1 < cx) & (y1 >= 0) & (y1 < cy) & (z1 >= 0) & (z1 < nz-1)
    cell1 = (z1*cy+y1)*cx+x1
    acc += tl.load(loc_ptr+cell1*24+3+r, mask=ok1, other=0.)
    x2 = x-0; y2 = y-1; z2 = z-0
    ok2 = m & (x2 >= 0) & (x2 < cx) & (y2 >= 0) & (y2 < cy) & (z2 >= 0) & (z2 < nz-1)
    cell2 = (z2*cy+y2)*cx+x2
    acc += tl.load(loc_ptr+cell2*24+6+r, mask=ok2, other=0.)
    x3 = x-1; y3 = y-1; z3 = z-0
    ok3 = m & (x3 >= 0) & (x3 < cx) & (y3 >= 0) & (y3 < cy) & (z3 >= 0) & (z3 < nz-1)
    cell3 = (z3*cy+y3)*cx+x3
    acc += tl.load(loc_ptr+cell3*24+9+r, mask=ok3, other=0.)
    x4 = x-0; y4 = y-0; z4 = z-1
    ok4 = m & (x4 >= 0) & (x4 < cx) & (y4 >= 0) & (y4 < cy) & (z4 >= 0) & (z4 < nz-1)
    cell4 = (z4*cy+y4)*cx+x4
    acc += tl.load(loc_ptr+cell4*24+12+r, mask=ok4, other=0.)
    x5 = x-1; y5 = y-0; z5 = z-1
    ok5 = m & (x5 >= 0) & (x5 < cx) & (y5 >= 0) & (y5 < cy) & (z5 >= 0) & (z5 < nz-1)
    cell5 = (z5*cy+y5)*cx+x5
    acc += tl.load(loc_ptr+cell5*24+15+r, mask=ok5, other=0.)
    x6 = x-0; y6 = y-1; z6 = z-1
    ok6 = m & (x6 >= 0) & (x6 < cx) & (y6 >= 0) & (y6 < cy) & (z6 >= 0) & (z6 < nz-1)
    cell6 = (z6*cy+y6)*cx+x6
    acc += tl.load(loc_ptr+cell6*24+18+r, mask=ok6, other=0.)
    x7 = x-1; y7 = y-1; z7 = z-1
    ok7 = m & (x7 >= 0) & (x7 < cx) & (y7 >= 0) & (y7 < cy) & (z7 >= 0) & (z7 < nz-1)
    cell7 = (z7*cy+y7)*cx+x7
    acc += tl.load(loc_ptr+cell7*24+21+r, mask=ok7, other=0.)
    tl.store(out_ptr+i, acc, mask=m)


@triton.jit
def _barrier_second(J, w, delta, act, scale):
    r = tl.maximum(act-J, 0.)/scale
    t = (tl.minimum(J, act)-delta)/scale
    logt = tl.where(r < .5, libdevice.log1p(-r), libdevice.log(t))
    q = r/t
    return w*(-2.*logt+4.*q+q*q)/(scale*scale)


@triton.jit(do_not_specialize=["nidx", "ncell", "ny", "nx", "cy", "cx"])
def ggn_diag_idx_kernel(u_ptr, k_ptr, out_ptr, idx_ptr, nidx, ncell, ny, nx, cy, cx, BLOCK: tl.constexpr):
    """Per-cell (8 vertices x 3 components) GGN diagonal contributions (soft + closed27 barrier)."""
    j = tl.program_id(0)*BLOCK+tl.arange(0, BLOCK)
    mj = j < nidx
    c = tl.load(idx_ptr+j, mask=mj, other=ncell).to(tl.int64)
    m = mj & (c < ncell)
    n0, n1, n2, n3, n4, n5, n6, n7 = _nodes(c, ny, nx, cy, cx)
    ihx = tl.load(k_ptr+0); ihy = tl.load(k_ptr+1); ihz = tl.load(k_ptr+2)
    g0 = tl.load(k_ptr+3); g1 = tl.load(k_ptr+4); g2 = tl.load(k_ptr+5)
    mu = tl.load(k_ptr+33); nu = tl.load(k_ptr+34)
    w = tl.load(k_ptr+35); delta = tl.load(k_ptr+36); act = tl.load(k_ptr+37); scale = tl.load(k_ptr+38)
    u0_0 = tl.load(u_ptr+n0*3+0, mask=m, other=0.)
    u0_1 = tl.load(u_ptr+n0*3+1, mask=m, other=0.)
    u0_2 = tl.load(u_ptr+n0*3+2, mask=m, other=0.)
    u1_0 = tl.load(u_ptr+n1*3+0, mask=m, other=0.)
    u1_1 = tl.load(u_ptr+n1*3+1, mask=m, other=0.)
    u1_2 = tl.load(u_ptr+n1*3+2, mask=m, other=0.)
    u2_0 = tl.load(u_ptr+n2*3+0, mask=m, other=0.)
    u2_1 = tl.load(u_ptr+n2*3+1, mask=m, other=0.)
    u2_2 = tl.load(u_ptr+n2*3+2, mask=m, other=0.)
    u3_0 = tl.load(u_ptr+n3*3+0, mask=m, other=0.)
    u3_1 = tl.load(u_ptr+n3*3+1, mask=m, other=0.)
    u3_2 = tl.load(u_ptr+n3*3+2, mask=m, other=0.)
    u4_0 = tl.load(u_ptr+n4*3+0, mask=m, other=0.)
    u4_1 = tl.load(u_ptr+n4*3+1, mask=m, other=0.)
    u4_2 = tl.load(u_ptr+n4*3+2, mask=m, other=0.)
    u5_0 = tl.load(u_ptr+n5*3+0, mask=m, other=0.)
    u5_1 = tl.load(u_ptr+n5*3+1, mask=m, other=0.)
    u5_2 = tl.load(u_ptr+n5*3+2, mask=m, other=0.)
    u6_0 = tl.load(u_ptr+n6*3+0, mask=m, other=0.)
    u6_1 = tl.load(u_ptr+n6*3+1, mask=m, other=0.)
    u6_2 = tl.load(u_ptr+n6*3+2, mask=m, other=0.)
    u7_0 = tl.load(u_ptr+n7*3+0, mask=m, other=0.)
    u7_1 = tl.load(u_ptr+n7*3+1, mask=m, other=0.)
    u7_2 = tl.load(u_ptr+n7*3+2, mask=m, other=0.)
    e0000 = (u1_0-u0_0)*ihx
    e0001 = (u5_0-u4_0)*ihx
    e0010 = (u3_0-u2_0)*ihx
    e0011 = (u7_0-u6_0)*ihx
    e0100 = (u1_1-u0_1)*ihx
    e0101 = (u5_1-u4_1)*ihx
    e0110 = (u3_1-u2_1)*ihx
    e0111 = (u7_1-u6_1)*ihx
    e0200 = (u1_2-u0_2)*ihx
    e0201 = (u5_2-u4_2)*ihx
    e0210 = (u3_2-u2_2)*ihx
    e0211 = (u7_2-u6_2)*ihx
    e1000 = (u2_0-u0_0)*ihy
